import {isAccountRoute,renderAccount,cancelAccountRender} from './account.js';
import {createFacilityMap} from './facility-map.js';
import {languages,normalizeLanguage,translate,localize} from './language.js';
import {facilities,wards,photoUrl,statusLabels,score,filterFacilities} from './data.js';
let facilityMap;
const $=s=>document.querySelector(s), main=$('#main'), dialog=$('#detail');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
let language=normalizeLanguage(read('js-language-v1','en'));
const refreshLanguage=()=>{document.documentElement.lang=language;localize(document.body,language)};
const currentRecords=items=>Array.isArray(items)?items.filter(item=>facilities.some(f=>f.id===item.facility)):[];
let assessments=currentRecords(read('js-assessments-v1',[])),ratings=currentRecords(read('js-ratings-v1',[]));
function save(key,data){try{localStorage.setItem(key,JSON.stringify(data));return true}catch{toast('Storage is unavailable. This change lasts only for this session.');return false}}
function toast(message){$('#toast').textContent=message;refreshLanguage();$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4200)}
const date=s=>s?`<time datetime="${esc(s)}">${new Date(s).toLocaleDateString(`${language}-IN`,{day:'numeric',month:'short',year:'numeric'})}</time>`:'Not assessed';
const badge=f=>`<span class="badge ${f.status}">${statusLabels[f.status]}</span>`;
const options=(items,current)=>items.map(x=>`<option ${x===current?'selected':''}>${esc(x)}</option>`).join('');
const facilityOptions=id=>facilities.map(f=>`<option value="${f.id}" ${id===f.id?'selected':''}>${esc(f.name)}</option>`).join('');
function intro(kicker,title,description,action=''){return `<section class="intro"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${description}</p></div>${action}</section>`}
function stats(items){return `<div class="stats">${items.map(([label,value,note,color=''])=>`<div class="stat"><span class="dot ${color}"></span><div class="label">${label}</div><strong>${value}</strong><small>${note}</small></div>`).join('')}</div>`}
function mapPage(){main.innerHTML=intro('YOUR NEIGHBOURHOOD, BETTER UNDERSTOOD','Find a place that works for you.','Explore civic amenities, see verified conditions, and help your community.',`<a class="button primary" href="#complaints/new">＋ Report a problem</a>`)+stats([['Listed amenities',facilities.length,'Thane dataset'],['Verified amenities',facilities.filter(f=>f.verified).length,'Confirmed by project owner'],['Needs attention',facilities.filter(f=>['partial','unusable'].includes(f.status)).length,'Partly usable or not usable','amber'],['Awaiting verification',facilities.filter(f=>!f.verified).length,'Amenity verification pending','grey']])+`<div class="toolbar"><input class="search" id="search" aria-label="Search facilities or wards" placeholder="⌕  Search an amenity or ward…"><select id="ward" aria-label="Ward">${options(['All wards',...wards])}</select><label class="button"><input id="usable" type="checkbox"> Usable only</label><label class="button"><input id="accessible" type="checkbox"> Step-free access</label></div><div class="chips" aria-label="Amenity types">${['All amenities',...new Set(facilities.map(f=>f.type))].map((t,i)=>`<button class="chip ${i?'':'selected'}" data-type="${t}" aria-pressed="${!i}">${t}</button>`).join('')}</div><div class="explorer"><section class="street-map-panel"><div class="map-actions"><strong>Thane street map</strong><button class="button" id="city-view">Entire Thane</button><button class="button" id="facility-view">Show facilities</button></div><div class="map street-map" id="thane-map" aria-label="Interactive street map of Thane" translate="no"></div><p class="note" id="map-message" role="status">Loading street map. Internet is required for roads and buildings.</p><div class="map-legend"><span><i class="dot"></i>Verified</span><span><i class="dot"></i>Usable</span><span><i class="dot amber"></i>Partly usable</span><span><i class="dot red"></i>Not usable</span><span><i class="dot grey"></i>Unverified</span></div></section><section><div class="list-head"><h2>Explore amenities</h2><span id="count"></span></div><div class="facility-list" id="facilities"></div></section></div><div class="callout"><div><h3>A listing is only the beginning.</h3><p>Field assessments show whether a facility is actually accessible, available and usable.</p></div><a class="button" href="#analytics">Explore the index ↗</a></div>`;
facilityMap=createFacilityMap($('#thane-map'),$('#map-message'),facilityDetail);$('#city-view').onclick=()=>facilityMap.cityView();$('#facility-view').onclick=()=>facilityMap.showFacilities();
let type='All amenities';function update(){const found=filterFacilities({query:'',ward:$('#ward').value,type,usable:$('#usable').checked,accessible:$('#accessible').checked}).filter(f=>`${f.name} ${f.ward??''} ${f.locality} ${f.facility_id} ${f.amenity_subtype.replaceAll('_',' ')} ${f.type} ${translate(f.name,language)} ${translate(f.ward??'',language)}`.toLocaleLowerCase().includes($('#search').value.toLocaleLowerCase()));$('#count').textContent=`${found.length} facilities · ${found.filter(f=>Number.isFinite(f.latitude)&&Number.isFinite(f.longitude)).length} mapped`;$('#facilities').innerHTML=found.map(f=>`<button class="facility" data-facility="${f.id}"><div class="facility-top"><div><h3>${esc(f.name)}</h3><p>${esc(f.type)} · ${esc(f.ward??'Ward unknown')}</p></div><span class="score" aria-label="Illustrative CAAUI score">${score(f.scores)??'—'}</span></div>${badge(f)}${Number.isFinite(f.latitude)&&Number.isFinite(f.longitude)?'':'<span class="note">Location pending</span>'}<span class="verified">${f.verified?date(f.verified):'Not yet verified'}</span></button>`).join('')||'<div class="empty">No matching amenities.<br>Try another filter or search.</div>';facilityMap.update(found);main.querySelectorAll('[data-facility]').forEach(b=>b.onclick=()=>{facilityMap.focus(b.dataset.facility);facilityDetail(b.dataset.facility)});refreshLanguage()}main.querySelectorAll('input,select').forEach(e=>e.addEventListener('input',update));main.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>{type=b.dataset.type;main.querySelectorAll('[data-type]').forEach(c=>{c.classList.toggle('selected',c===b);c.setAttribute('aria-pressed',c===b)});update()});update();}
function show(content){$('#detail-content').innerHTML=`<button class="close" aria-label="Close dialog">×</button>${content}`;$('.close').onclick=()=>dialog.close();refreshLanguage();dialog.showModal()}
function facilityDetail(id){
  const f=facilities.find(f=>f.id===id);
  if(!f)return;
  show(`<h1>${esc(f.name)}</h1>
    <div class="facility-photos">${[f.cover_photo_path,...f.photos.filter(p=>p!==f.cover_photo_path)].filter(Boolean).map((p,i)=>`<a href="${esc(photoUrl(p))}" target="_blank" rel="noopener"><img loading="lazy" src="${esc(photoUrl(p))}" alt="${esc(f.name)} — Photo ${i+1}"></a>`).join('')}</div>
    <section class="panel"><h2>Report a problem</h2><p>Something wrong with this amenity? Let us know.</p><a class="button primary" id="report-link" href="#complaints/new/${id}">Report a problem</a></section>
    <form id="rating-form"><h2>Share feedback</h2><label>Your rating<select name="rating">${options(['5','4','3','2','1'])}</select></label><label>Feedback<textarea name="feedback" maxlength="500" required></textarea></label><button class="button primary">Submit feedback</button></form>
    <section class="amenity-reviews" aria-labelledby="reviews-heading"><h2 id="reviews-heading">Reviews</h2><div id="amenity-reviews" aria-live="polite"></div></section>`);
  $('#report-link').onclick=()=>dialog.close();
  function renderReviews(){
    const reviews=ratings.filter(r=>r.facility===id).slice().reverse();
    $('#amenity-reviews').innerHTML=reviews.length?reviews.map(r=>`<article class="audit"><strong>${esc(r.rating)} / 5 ★</strong><small>${date(r.at)}</small><p translate="no">${esc(r.feedback)}</p></article>`).join(''):'<p class="note">No reviews yet. Be the first to share feedback.</p>';
    refreshLanguage();
  }
  renderReviews();
  $('#rating-form').onsubmit=e=>{
    e.preventDefault();
    const d=new FormData(e.target), feedback=String(d.get('feedback')??'').trim(), rating=Number(d.get('rating'));
    if(!feedback||feedback.length>500||!Number.isInteger(rating)||rating<1||rating>5){toast('Please enter feedback and a rating from 1 to 5.');return}
    ratings.push({facility:id,rating,feedback,at:new Date().toISOString()});
    const persisted=save('js-ratings-v1',ratings);
    e.target.reset();
    renderReviews();
    $('#amenity-reviews').scrollIntoView({block:'nearest'});
    if(persisted)toast('Feedback added to reviews and saved on this device.');
  };
}
function analytics(){const scores=facilities.map(f=>score(f.scores)).filter(x=>x!==null);main.innerHTML=intro('EVIDENCE FOR BETTER DECISIONS','Look beyond the number of facilities.','Review Thane facility coverage and verification gaps.',`<button class="button" id="export">↓ Export facility CSV</button>`)+stats([['Illustrative mean CAAUI',score(scores)??'Insufficient data','No scores without assessments'],['Verified amenities',facilities.filter(f=>f.verified).length+' / '+facilities.length,'Confirmed by project owner'],['Fully usable',facilities.filter(f=>f.status==='usable').length+' / '+facilities.length,'Unknown is not unusable'],['Facility photos',facilities.reduce((n,f)=>n+f.photos.length,0),'Source documentation','amber']])+`<div class="two-col"><section class="panel"><h2>Facility score comparison</h2><p>CAAUI · 0–100 · illustrative equal weights</p>${facilities.map(f=>`<div class="bar-row"><span>${esc(f.name)}</span><div class="bar"><i style="width:${score(f.scores)??0}%"></i></div><strong>${score(f.scores)??'—'}</strong></div>`).join('')}</section><section class="panel"><h2>Provision–usability gap</h2><p>Imported listings compared with verified usable facilities.</p><div class="table-wrap"><table><thead><tr><th>WARD</th><th>LISTED</th><th>USABLE</th><th>PARTLY</th></tr></thead><tbody>${wards.map(w=>{const fs=facilities.filter(f=>(f.ward??'Ward unknown')===w);return `<tr><td>${esc(w)}</td><td>${fs.length}</td><td>${fs.filter(f=>f.status==='usable').length}</td><td>${fs.filter(f=>f.status==='partial').length}</td></tr>`}).join('')}</tbody></table></div><h3 style="margin-top:28px">Where to start</h3><p>Confirm entrance locations, wards and service conditions on site before assigning scores. Photo timestamps are not assessment dates.</p><p class="note">Ward coverage-adjusted scores need population and geographic data. They are not calculated in this skeleton.</p></section></div><section class="panel"><h2>A transparent starting point</h2><p>Each available dimension contributes equally to the demo facility score. Missing values are excluded, never scored as zero. Research weights, normalisation, score version history and regional coverage metrics remain to be defined.</p></section>`;$('#export').onclick=()=>{const rows=[['facility_id','facility','ward','type','field_status','last_verified','illustrative_caaui'],...facilities.map(f=>[f.id,f.name,f.ward,f.type,f.status,f.verified??'',score(f.scores)??''])];const csv=rows.map(r=>r.map(c=>'"'+String(c).replaceAll('"','""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='jansuvidha-thane-facilities.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};}
function assessment(){main.innerHTML=intro('FIELDWORK','Better evidence starts on the ground.','A structured assessment form for the first survey workflow.')+`<div class="two-col"><section class="panel"><h2>Save an assessment draft</h2><p>Drafts stay on this device and do not change verified facility status.</p><form id="assessment-form"><label>Facility<select name="facility">${facilityOptions()}</select></label><label>Assessment date<input name="date" type="date" value="${new Date().toISOString().slice(0,10)}" required></label><label>Observed condition<select name="condition">${options(['Usable','Partly usable','Not usable','Unable to assess'])}</select></label><div class="checks"><label><input type="checkbox" name="water"> Water available</label><label><input type="checkbox" name="accessible"> Step-free access</label><label><input type="checkbox" name="clean"> Clean</label></div><label>Field notes<textarea name="notes" required maxlength="1500"></textarea></label><button class="button primary">Save local draft</button><span class="support">GPS, timestamped photos and surveyor verification are required before a draft can become field evidence.</span></form></section><section class="panel"><h2>Assessment drafts</h2><div id="drafts"></div></section></div>`;function update(){$('#drafts').innerHTML=assessments.length?assessments.map(a=>`<div class="audit"><strong>${esc(facilities.find(f=>f.id===a.facility)?.name)}</strong><small>${esc(a.date)} · ${esc(a.condition)} · Draft only</small><p translate="no">${esc(a.notes)}</p></div>`).join(''):'<div class="empty">No drafts yet.<br>Your first fieldwork starts here.</div>';refreshLanguage()}update();$('#assessment-form').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);if(!String(d.get('notes')).trim()){toast('Please add field notes.');return}assessments.unshift({...Object.fromEntries(d),created:new Date().toISOString()});save('js-assessments-v1',assessments);update();toast('Assessment draft saved locally.');};}
function render(){cancelAccountRender();facilityMap?.destroy();facilityMap=null;const [page='map',action,id]=location.hash.slice(1).split('/');const names={map:'Suvidha Map',complaints:'My complaints',government:'Government portal',analytics:'Analytics',assessment:'Field assessment'};$('#breadcrumb').textContent=names[page]??names.map;document.querySelectorAll('nav a').forEach(a=>{const active=a.hash==='#'+page;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});if(isAccountRoute(page)){renderAccount(page,action,id);return;}else if(page==='analytics')analytics();else if(page==='assessment')assessment();else mapPage();refreshLanguage();}
const languageSelect=$('#language');
const themeSelect=$('#theme');
themeSelect.value=document.documentElement.dataset.theme;
themeSelect.onchange=()=>{
  document.documentElement.dataset.theme=themeSelect.value;
  save('js-theme-v1',themeSelect.value);
};
languageSelect.innerHTML=Object.entries(languages).map(([code,label])=>`<option value="${code}" lang="${code}">${label}</option>`).join('');
languageSelect.value=language;
languageSelect.onchange=()=>{language=normalizeLanguage(languageSelect.value);save('js-language-v1',language);refreshLanguage()};
window.addEventListener('hashchange',render);render();
